import java.util.Scanner;

public class Main {
    static final int MAXNODES = 1000005;
    static boolean[] checked = new boolean[MAXNODES];

    static long computePower(long base, int exp) {
        long res = 1;
        long mod = 1000000007;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(computePower(p, (int)(p - 1)));
            sc.close();
            return;
        }
        if (k == 1) {
            System.out.println(computePower(p, (int)p));
            sc.close();
            return;
        }

        int totalGroups = 0;
        for (int i = 1; i < p; i++) {
            if (checked[i]) continue;
            long current = i;
            while (!checked[(int)current]) {
                checked[(int)current] = true;
                current = (current * k) % p;
            }
            totalGroups++;
        }
        System.out.println(computePower(p, totalGroups));
        sc.close();
    }
}
